(()=>{const A=['audit','model','training'];let step=0,placed={},running=false;function card(i){return '<button class="lab-card" draggable="true" data-card="'+i+'" aria-label="Citra MRI contoh '+(i+1)+'"><img src="assets/slice-'+(i%3)+'.png" alt=""><span>MRI-'+String(i+1).padStart(2,'0')+'</span></button>'}function draw(){const m=document.getElementById('main');m.innerHTML='<div class="lab-page"><div class="page-back"><a href="#markas">Markas</a><span>/</span>Laboratorium Eksperimen</div><header class="game-title"><div><span class="eyebrow">'+window.UI.icon('flask')+' PRAKTIK LANGSUNG</span><h1>Laboratorium Eksperimen</h1><p>Kamu yang mengoperasikan pipeline riset. Siapkan data, pasang CBAM, lalu jalankan satu eksperimen.</p></div><div class="game-track">'+window.UI.ticks(step,3)+'<span>Stasiun '+(step+1)+' / 3</span></div></header><div class="lab-workbench panel"><div class="lab-tabs"><button class="'+(step===0?'selected':'')+'" data-lab-step="0">01 Audit data</button><button class="'+(step===1?'selected':'')+'" data-lab-step="1">02 Rakit model</button><button class="'+(step===2?'selected':'')+'" data-lab-step="2">03 Jalankan eksperimen</button></div>'+[audit,model,run][step]()+'</div></div>';bind()}function audit(){return '<div class="lab-head"><span class="step-kicker">STASIUN 01 · AUDIT DATA</span><h2>Seret citra ke partisi dataset</h2><p>Tarik setiap citra ke data latih, validasi, atau uji. Contoh target: 4 latih, 1 validasi, 1 uji.</p></div><div class="lab-cards">'+[0,1,2,3,4,5].map(card).join('')+'</div><div class="drop-grid">'+[['train','Data latih'],['val','Validasi'],['test','Data uji']].map(x=>'<div class="drop-zone" data-drop="'+x[0]+'"><h3>'+x[1]+'</h3><p>Taruh citra di sini</p><div class="drop-items">'+Object.entries(placed).filter(y=>y[1]===x[0]).map(y=>'<span>'+('MRI-'+String(Number(y[0])+1).padStart(2,'0'))+'</span>').join('')+'</div></div>').join('')+'</div><div class="lab-actions"><button class="btn primary" data-lab-next="'+(Object.keys(placed).length===6?'1':'0')+'">Lanjut ke perakitan</button><span class="lab-status">'+Object.keys(placed).length+'/6 citra dipindahkan</span></div>'}function model(){return '<div class="lab-head"><span class="step-kicker">STASIUN 02 · ARSITEKTUR</span><h2>Hubungkan jalur fitur CBAM</h2><p>Tekan modul dalam urutan operasi. Perhatikan bagaimana fitur melewati channel attention, spatial attention, pooling, lalu classifier.</p></div><div class="pipeline">'+['Backbone B0','Channel attention','Spatial attention','Global average pooling','Classifier'].map((x,i)=>'<button class="node '+(i<step?'on':'')+'" data-node="'+i+'">'+x+'</button>').join('<span class="connector">→</span>')+'</div><div class="lab-actions"><button class="btn primary" data-lab-next="'+(step>=1?'2':'1')+'">'+(step>=1?'Lanjut ke eksperimen':'Jalankan jalur fitur')+'</button><span class="lab-status">Klik modul perhatian untuk melihat aliran data.</span></div>'}function run(){return '<div class="lab-head"><span class="step-kicker">STASIUN 03 · EKSPERIMEN</span><h2>Jalankan model dan baca hasilnya</h2><p>Semua pengaturan sudah disamakan. Tekan tombol untuk menjalankan simulasi pasangan B0 dan B0 + CBAM.</p></div><div class="run-console"><div class="console-screen"><div class="console-line">dataset_audit ........ READY</div><div class="console-line">split_70_15_15 ....... READY</div><div class="console-line">efficientnet_b0 ...... READY</div><div class="console-line">cbam_module .......... READY</div><div class="console-line '+(running?'flash':'')+'">'+(running?'running seven seeds ...':'waiting for run command')+'</div></div><button class="btn primary run-btn" data-run>Jalankan 7 seed</button></div>'+(running?'<div class="result-grid"><div><span>B0 standar</span><strong>80%</strong></div><div><span>B0 + CBAM</span><strong>84%</strong></div><div class="gain"><span>Perubahan macro-F1</span><strong>+4 poin</strong></div></div><p class="lab-note">Simulasi pembelajaran. Hasil skripsi berasal dari model PyTorch yang kamu latih pada dataset yang sudah diaudit.</p>':'')}function bind(){document.querySelectorAll('[data-lab-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.labStep;draw()});document.querySelectorAll('[data-card]').forEach(b=>{b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.card);b.onclick=()=>{const id=b.dataset.card;placed[id]=placed[id]?null:'train';if(!placed[id])delete placed[id];draw()}});document.querySelectorAll('[data-drop]').forEach(z=>{z.ondragover=e=>e.preventDefault();z.ondrop=e=>{e.preventDefault();placed[e.dataTransfer.getData('text/plain')]=z.dataset.drop;draw()}});document.querySelectorAll('[data-lab-next]').forEach(b=>b.onclick=()=>{if(b.dataset.labNext==='1'&&Object.keys(placed).length<6)return;step=+b.dataset.labNext;draw()});const r=document.querySelector('[data-run]');if(r)r.onclick=()=>{running=true;draw()};document.querySelectorAll('[data-node]').forEach((n,i)=>n.onclick=()=>{if(i===1||i===2){n.classList.add('on')}})}window.Lab={start:()=>{step=0;placed={};running=false;draw()}}})();
